/* Pure chapter-three models. Payoffs are benefits; maximize. No network dependencies. */
(function(root){'use strict';
const finite=(x,n)=>{if(!Number.isFinite(x))throw Error(n+'必须是有限数值');return x;};
const prob=(x,n='概率')=>{finite(x,n);if(x<0||x>1)throw Error(n+'必须在 0—1 之间');return x;};
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);
function vector(p){if(!Array.isArray(p)||!p.length)throw Error('概率向量不能为空');p.forEach(x=>prob(x));if(Math.abs(p.reduce((a,b)=>a+b,0)-1)>1e-9)throw Error('概率之和必须为 1');}
function best(v){const value=Math.max(...v);return {value,indices:v.map((x,i)=>Math.abs(x-value)<1e-9?i:-1).filter(i=>i>=0)};}
function matrix(a,p){vector(p);if(!Array.isArray(a)||!a.length)throw Error('至少一个方案');a.forEach(r=>{if(r.length!==p.length)throw Error('损益表维度不一致');r.forEach(x=>finite(x,'损益'));});}
function evaluate(a,p){matrix(a,p);const ev=a.map(r=>dot(r,p)),perfect=dot(p,p.map((_,j)=>Math.max(...a.map(r=>r[j]))));return {ev,best:best(ev),perfect,evpi:Math.max(0,perfect-Math.max(...ev)),eol:a.map(r=>dot(p,r.map((x,j)=>Math.max(...a.map(t=>t[j]))-x))),sd:a.map((r,i)=>Math.sqrt(dot(p,r.map(x=>(x-ev[i])**2)))),loss:a.map(r=>dot(p,r.map(x=>x<0?1:0)))};}
function bayes(a,p,likelihood,cost=0){matrix(a,p);finite(cost,'调查费');if(cost<0)throw Error('调查费不能为负');if(!likelihood.length)throw Error('需要报告类别');p.forEach((_,j)=>vector(likelihood.map(r=>r[j])));const prior=evaluate(a,p);const reports=likelihood.map(row=>{if(row.length!==p.length)throw Error('似然表维度不一致');const joint=row.map((v,j)=>v*p[j]),mass=joint.reduce((s,x)=>s+x,0);if(mass===0)return {mass,joint,posterior:null,ev:null,best:null,contribution:0};const posterior=joint.map(x=>x/mass),ev=a.map(r=>dot(r,posterior));return {mass,joint,posterior,ev,best:best(ev),contribution:Math.max(...a.map(r=>dot(r,joint)))};});const gross=reports.reduce((s,r)=>s+r.contribution,0),evsi=Math.max(0,gross-prior.best.value);return {prior,reports,gross,evsi,net:gross-cost,increment:evsi-cost,cost};}
const cafe=[[0,0],[8,2],[16,-6]],names=['不投资','小店','大店'];
function simulate(a,p,n,seed){matrix(a,p);if(!Number.isInteger(n)||n<1||n>10000)throw Error('次数须为 1—10000 的整数');if(!Number.isInteger(seed)||seed<0||seed>4294967295)throw Error('种子须为 0—4294967295 的整数');let state=seed>>>0;const sums=a.map(()=>0),counts=p.map(()=>0),paths=a.map(()=>[]);for(let t=1;t<=n;t++){state=(Math.imul(1664525,state)+1013904223)>>>0;let u=state/4294967296,j=0,c=p[0];while(u>=c&&j<p.length-1)c+=p[++j];counts[j]++;a.forEach((r,i)=>{sums[i]+=r[j];if(t<=10||t%Math.max(1,Math.floor(n/160))===0||t===n)paths[i].push([t,sums[i]/t]);});}return {counts,means:sums.map(x=>x/n),paths};}
function tree(cost=210){finite(cost,'扩建费');if(cost<0||cost>1000)throw Error('扩建费须在 0—1000 万元');const expand=7*(.85*150+.15*10)-cost,stayGood=7*(.85*60+.15*2),stayBad=7*(.1*60+.9*2),medium=3*(.75*100+.25*10)+.75*7*(.85*150+.15*10)+.25*7*(.1*150+.9*10)-400,small=3*(.75*60+.25*2)+.75*Math.max(expand,stayGood)+.25*stayBad-150;return {expand,stayGood,stayBad,medium,small,late:best([expand,stayGood]),root:best([medium,small])};}
function sensitivity(a){matrix(a,[.5,.5]);const cuts=[0,1];for(let i=0;i<a.length;i++)for(let j=i+1;j<a.length;j++){const den=(a[i][0]-a[i][1])-(a[j][0]-a[j][1]);if(Math.abs(den)>1e-12){const p=(a[j][1]-a[i][1])/den;if(p>0&&p<1)cuts.push(p);}}const sorted=[...new Set(cuts)].sort((x,y)=>x-y);return sorted.slice(0,-1).map((lo,i)=>({lo,hi:sorted[i+1],best:evaluate(a,[(lo+sorted[i+1])/2,1-(lo+sorted[i+1])/2]).best.indices}));}
function utility(x,k,lo=-10,hi=20){finite(x,'结果');finite(k,'曲率');if(k< -5||k>5||hi<=lo||x<lo-1e-10||x>hi+1e-10)throw Error('效用输入超出定义域');const z=(x-lo)/(hi-lo);return Math.abs(k)<1e-8?z:-Math.expm1(-k*z)/(-Math.expm1(-k));}
function inverse(u,k,lo=-10,hi=20){prob(u,'效用');return lo+(hi-lo)*(Math.abs(k)<1e-8?u:-Math.log1p(u*Math.expm1(-k))/k);}
function utilityChoice(k){const a=[[5,5],[20,-10]],p=[.5,.5],eu=a.map(r=>dot(p,r.map(x=>utility(x,k))));return {a,ev:[5,5],eu,ce:eu.map(u=>inverse(u,k)),best:best(eu),points:Array.from({length:61},(_,i)=>{const x=-10+i*.5;return [x,utility(x,k)];})};}
function binom(n,k,p){if(p===0)return k===0?1:0;if(p===1)return k===n?1:0;let c=1;for(let i=1;i<=k;i++)c*= (n-i+1)/i;return c*p**k*(1-p)**(n-k);}
function sampling(n,fixed=0,unit=.02){if(!Number.isInteger(n)||n<0||n>40)throw Error('样本数须为 0—40 的整数');[fixed,unit].forEach(x=>{finite(x,'费用');if(x<0||x>10)throw Error('费用须在 0—10 元');});const p=[.5,.3,.2],theta=[.2,.1,.05],a=[[0,0,0],[-5,5,10]],l=Array.from({length:n+1},(_,k)=>theta.map(t=>binom(n,k,t))),b=bayes(a,p,l,n?fixed+n*unit:0);return {...b,n};}
const api={dot,best,evaluate,bayes,cafe,names,simulate,tree,sensitivity,utility,inverse,utilityChoice,sampling};
if(typeof module==='object'&&module.exports)module.exports=api;root.Ch3=api;
})(typeof globalThis!=='undefined'?globalThis:this);
